and I.GRADE_DATE =( select max(a.GRADE_DATE) from MST_BOND_CREDIT_RATING a where a.O_TYPE='01' and a.O_CODE= I.O_CODE and a.GRADE_DATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
) and I.GRADE_RESULT = ( select max(GRADE_RESULT) from MST_BOND_CREDIT_RATING where O_TYPE='01' and O_CODE= I.O_CODE and GRADE_DATE = I.GRADE_DATE )
) GRADE_RESULT FROM FIN_DEAL_PLEDGE A LEFT JOIN TRD_PRODUCT_DEAL B ON A.FINPROD_ID = B.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE C ON A.PLEDGE_FINPROD_ID = C.FINPROD_ID LEFT JOIN FIN_PRODUCT D ON A.PLEDGE_FINPROD_ID = D.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO_ADD E ON E.CUSTOMER_ID = D.ISSUER LEFT JOIN FIN_PRODUCT_ADD F ON A.PLEDGE_FINPROD_ID = F.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD G ON G.TRADE_ID = B.TRADE_ID LEFT JOIN ETR_ENTRUST M ON G.ENTRUST_ID = M.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD K ON G.ENTRUST_ID = K.ENTRUST_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON G.PORTFOLIO_ID=fpa.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT H ON A.FINPROD_ID = H.FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL J ON J.TRADE_ID = B.TRADE_ID LEFT JOIN MST_COUNTER_PARTY mcp on H.COUNTER_ID = mcp.COUNTER_ID LEFT JOIN trd_fin_product_deal_total L /** 金融产品临时交易1 **/ ON H.finprod_id = L.finprod_id AND H.branch = L.branch AND L.ps in ('T54', 'T07', 'T93', 'T56') WHERE 1=1 AND B.TRADE_STATUS='01'AND B.IS_CANCEL='N' and F.IS_SEC_BOND = 'N' AND J.BACK_LEND_DIRECTION=#{BACK_LEND_DIRECTION_03} AND K.ASSET_TYPE1 = 'H01' AND G.ENTRUST_ID is not null AND L.totle_trade_id is null
AND (H.VDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD'))
AND not exists( select TT.FINPROD_ID from TRD_FIN_PRODUCT_DEAL_TOTAL TT where TT.PS in ('T07','T96','T95','T93') AND TT.FINPROD_ID = H.FINPROD_ID AND TT.TRADE_STATUS = '01' AND TT.IS_CANCEL = 'N' AND TT.TRADE_DATE <= TO_DATE(#{sysDate},'YYYY-MM-DD') )
