select sum(stasec.pleAmt) * stasec.pledgeRatio as PLEDGE_AMT, stasec.pledgeRatio * 100 as pledgeRatio, sum(stasec.pleAmt) as pledgeFaceValue, stasec.type_4, stasec.type_5, stasec.finprodType2, stasec.finprodMarketId, stasec.finprodAbbr, stasec.registOrg, stasec.companyNature, stasec.isSecBond, stasec.counterId, null, null, null, null, null, stasec.gradeResult from (
select nvl(pspf.amount,0)*100 pleAmt , nvl(fscr.scale,0) as pledgeRatio, C.TYPE_4, C.TYPE_5, '标准债' as finprodType2, fp.finprod_market_id as finprodMarketId, fp.FINPROD_ABBR as finprodAbbr, fp.REGIST_ORG as registOrg, decode(E.PARTY_TYPE2, '01', '国有企业', '02', '集体企业', '03', '民营企业', '04', '外资企业', '05', '公众企业', '99', '其他企业') companyNature, (CASE WHEN F.IS_SEC_BOND = 'Y' THEN '次级债' ELSE null END) isSecBond, pp.PORTFOLIO_ID counterId, ( select decode(I.GRADE_RESULT,'01','AAA+','02','AAA','03','AAA-','04','AA+','05','AA','06','AA-','07','A+','08','A','09','A-','10','A-1','11','A-2','12','A-3','13','BBB+','14','BBB','15','BBB-','16','BB+','17','BB','18','BB-','19','B+','20','B','21','B-','22','CCC+','23','CCC','24','CCC-','25','CC+','26','CC','27','CC-','28','C+','29','C','30','C-','31','D','') from MST_BOND_CREDIT_RATING I where I.O_TYPE = '01' and I.O_CODE = fp.FINPROD_MARKET_ID and I.GRADE_DATE <= TO_DATE(#{sysDate},'YYYY-MM-DD') and I.GRADE_DATE =( select max(a.GRADE_DATE) from MST_BOND_CREDIT_RATING a where a.O_TYPE='01' and a.O_CODE= I.O_CODE and a.GRADE_DATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
) and I.GRADE_RESULT = ( select max(GRADE_RESULT) from MST_BOND_CREDIT_RATING where O_TYPE='01' and O_CODE= I.O_CODE and GRADE_DATE = I.GRADE_DATE ) ) gradeResult from trd_stasec_flow tsf left join trd_stasec_flow_detail tsfd on tsfd.seqno=tsf.seqno and tsfd.BRANCH = '0' left join ptl_sec_position_flow pspf on tsf.seqno =pspf.trade_id and pspf.finprod_id=tsfd.finprod_id AND tsf.portfolio_id = pspf.portfolio_id and tsf.sec_acct_id = pspf.sec_acct_id and tsf.cdate = pspf.cdate left join ptl_portfolio pp on pp.portfolio_id = tsf.portfolio_id left join fin_product fp on fp.finprod_id=tsfd.finprod_id LEFT JOIN MST_CUSTOMER_INFO_ADD E ON E.CUSTOMER_ID = fp.ISSUER LEFT JOIN FIN_PRODUCT_ADD F ON fp.finprod_id = F.FINPROD_ID left join fin_product_type C on fp.finprod_id=C.Finprod_Id LEFT JOIN FIN_PRODUCT_ADD fpa ON pp.PORTFOLIO_ID=fpa.PORTFOLIO_ID left join fin_stdsec_converse_radio fscr ON fscr.finprod_id = tsfd.finprod_id AND fscr.BRANCH = '0' and fscr.vdate <= TO_DATE(#{sysDate},'YYYY-MM-DD') and fscr.mdate >= TO_DATE(#{sysDate},'YYYY-MM-DD') where tsf.cdate <= TO_DATE(#{sysDate},'YYYY-MM-DD')
#{counterId,jdbcType=VARCHAR}
AND fpa.PROD_MANAGER IN
#{item}
AND fp.finprod_market_id LIKE CONCAT(CONCAT('%',#{finprodMarketId}),'%')
AND C.TYPE_4 = #{type4}
AND C.TYPE_5 = #{type5}
)stasec group by stasec.pledgeRatio, stasec.type_4, stasec.type_5, stasec.finprodType2, stasec.finprodMarketId, stasec.finprodAbbr, stasec.registOrg, stasec.companyNature, stasec.isSecBond, stasec.counterId, stasec.gradeResult ) tt
where 1=1
#{busiType,jdbcType=VARCHAR}

SELECT fpd.TRADE_ID businessCode, tpd.BUSI_TYPE tradeType, tpd.TRADE_ID sourceBusinessCode, tpda.ENTRUST_ID entrustCode, pp.PORTFOLIO_ID portfolioId, pp.portfolio_name portfolioName, fp.finprod_market_id finprodId, fp.finprod_abbr finprodName, ptpd.back_lend_direction tradePs, tpd.share_amt tradeAmt, ftp.TRADE_MARKET tradeMarket, tpd.TRADE_DATE tradeDate, tpd.vdate vPayDate, tpd.mdate mPayDate, ftp.TERM_TYPE termType, tpd.mdate-tpd.vdate actCapDays, fpd.trade_date pledgeSubstitutionDate, tpd.CCY ccy, tpd.REMARK remark FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID LEFT JOIN PTL_TRADE PT ON tpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO pp ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT ftp ON ((tpd.TRADE_STATUS = '01' AND ftp.FINPROD_ID = tpd.TRADE_ID)) LEFT JOIN FIN_PLEDGE_DISPLACE fpd ON tpd.trade_id=fpd.f_trade_id left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on tfpdt.TOTLE_TRADE_ID = fpd.TRADE_ID LEFT JOIN FIN_PLEDGE_DISPLACE_RESULT fpdr ON fpd.trade_id=fpdr.trade_id LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID LEFT JOIN FIN_DEAL_TARGET fdt on tpd.TRADE_ID = fdt.FINPROD_ID LEFT JOIN FIN_PRODUCT fp ON fp.finprod_id =fdt.pledge_finprod_id WHERE pp.INVEST_YESORNO = 'Y' and fpd.trade_id is not null
and (tfpdt.PS != 'T93' or tfpdt.PS is null)
#{portfolioId,jdbcType=VARCHAR}
AND ( tpd.TRADE_DATE <= TO_DATE(#{substitutionTradeEndDate},'YYYY-MM-DD') AND TO_DATE(#{substitutionTradeStartDate},'YYYY-MM-DD') <= tpd.TRADE_DATE)
AND ( fpd.TRADE_DATE <= TO_DATE(#{substitutionEndDate},'YYYY-MM-DD') AND TO_DATE(#{substitutionStartDate},'YYYY-MM-DD') <= fpd.TRADE_DATE)
AND ptpd.back_lend_direction=#{tradePs,jdbcType=VARCHAR}
AND tpd.BUSI_TYPE=#{tradeType,jdbcType=VARCHAR}
GROUP BY fpd.TRADE_ID,tpd.BUSI_TYPE,tpd.TRADE_ID,tpda.ENTRUST_ID,pp.PORTFOLIO_ID,pp.portfolio_name, fp.finprod_market_id,fp.finprod_abbr,ptpd.back_lend_direction,tpd.share_amt,ftp.TRADE_MARKET,tpd.TRADE_DATE, tpd.vdate,tpd.mdate,ftp.TERM_TYPE,ftp.act_cap_days,fpd.trade_date,tpd.CCY,tpd.REMARK ORDER BY fpd.TRADE_DATE DESC

select T3.* from ( select INFO.PORTFOLIO_ID portfolioId, INFO.PORTFOLIO_NAME portfolioName, INFO.FINPROD_MARKET_ID secid, INFO.FINPROD_NAME secName, INFO.REGIST_ORG registOrg, sum(nvl(INFO.prinAmt, 0)) prinAmt, /*持仓券面*/ sum(nvl(INFO.canpledgeAmt, 0)) canpledgeAmt, /*可质押券面*/ sum(nvl(INFO.pledgeAmt, 0)) pledgeAmt,/*已质押券面*/ sum(nvl(INFO.canpledgeAmt, 0)) - sum(nvl(INFO.pledgeAmt, 0)) remainAmt from ( /*债券买入-卖出-回售-赎回*/ SELECT wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, sum(NVL(decode(WTPD.PS, 'T01',wtpd.SHARE_AMT,-1 * wtpd.SHARE_AMT), 0) * 100) AS prinAmt ,/*持仓券面*/ sum(NVL(decode(WTPD.PS, 'T01',wtpd.SHARE_AMT,-1 * wtpd.SHARE_AMT), 0) * 100) AS canpledgeAmt, /*可质押券面*/ 0 pledgeAmt/*已质押券面*/ FROM TRD_PRODUCT_DEAL wtpd LEFT JOIN TRD_PRODUCT_DEAL_ADD wtpda ON wtpd.TRADE_ID = wtpda.TRADE_ID inner JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = wtpd.FINPROD_ID WHERE wtpd.FINPROD_TYPE2 = 'F01' AND wtpd.PS IN ( 'T01' , 'T02' , 'T03' , 'T39' ) AND (wtpd.IS_CANCEL IS NULL OR wtpd.IS_CANCEL = 'N') AND wtpd.TRADE_STATUS = '01' /*组合代码*/
and wtpda.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ and wtpd.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd')
group by wtpd.TRADE_ID,wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG
union all /*债券到期*/ SELECT /*汇总交易.组合代码 组合*/ TOTAL.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, -1 * sum(nvl(ROUND(TOTAL.SHARE_AMT,2), 0) * 100) prinAmt, /*持仓券面*/ -1 * sum(nvl(ROUND(TOTAL.SHARE_AMT,2), 0) * 100) canpledgeAmt, /*可质押券面*/ 0 pledgeAmt/*已质押券面*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID inner JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = TOTAL.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = TOTAL.FINPROD_ID /*检索条件*/ WHERE 1 = 1 and PA_TOTAL.PA_BUSS_TYPE = '37' AND (TOTAL.IS_CANCEL IS NULL OR TOTAL.IS_CANCEL = 'N') AND TOTAL.TRADE_STATUS = '01' and total.PORTFOLIO_ID is not null /*组合代码*/
and total.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ and TOTAL.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') group by TOTAL.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG
union all
/*债券中间还本*/ SELECT /*汇总交易.组合代码 组合*/ TOTAL.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, -1 * sum(nvl(ROUND(TOTAL.PRIN_AMT,2), 0)) prinAmt, /*持仓券面*/ -1 * sum(nvl(ROUND(TOTAL.PRIN_AMT,2), 0)) canpledgeAmt, /*可质押券面*/ 0 pledgeAmt/*已质押券面*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID inner JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = TOTAL.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = TOTAL.FINPROD_ID /*检索条件*/ WHERE 1 = 1 and PA_TOTAL.PA_BUSS_TYPE = '36' AND (TOTAL.IS_CANCEL IS NULL OR TOTAL.IS_CANCEL = 'N') AND TOTAL.TRADE_STATUS = '01' and total.PORTFOLIO_ID is not null /*组合代码*/
and total.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ and TOTAL.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') group by TOTAL.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG
union all /*回购交易：正回购、逆回购*/ SELECT TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, FIN_PRODUCT.FINPROD_MARKET_ID, FIN_PRODUCT.FINPROD_ABBR AS FINPROD_NAME, FIN_PRODUCT.REGIST_ORG, 0 prinAmt, /*持仓券面*/ decode(TRD_PRODUCT_DEAL.FINPROD_TYPE2, 'F05', FIN_DEAL_PLEDGE.PLEDGE_NUMBER * 100,'F04', -FIN_DEAL_PLEDGE.PLEDGE_NUMBER * 100, 0) canpledgeAmt, /*可质押券面*/ decode(TRD_PRODUCT_DEAL.FINPROD_TYPE2, 'F02', FIN_DEAL_PLEDGE.PLEDGE_NUMBER * 100, 0) pledgeAmt /*已质押券面*/ FROM TRD_PRODUCT_DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD ON TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ON TRD_PRODUCT_DEAL.TRADE_ID = PA_TRD_PRODUCT_DEAL.TRADE_ID inner JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID LEFT JOIN FIN_DEAL_PLEDGE ON TRD_PRODUCT_DEAL.TRADE_ID = FIN_DEAL_PLEDGE.FINPROD_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT H ON FIN_DEAL_PLEDGE.FINPROD_ID = H.FINPROD_ID /*修改关联条件 2019/3/6 end*/ LEFT JOIN trd_fin_product_deal_total L /** 金融产品临时交易1 **/ ON H.finprod_id = L.finprod_id AND H.branch = L.branch AND L.ps in ('T54', 'T07', 'T93', 'T56') WHERE TRD_PRODUCT_DEAL.FINPROD_TYPE2 IN ('F02', 'F04', 'F05') AND TRD_PRODUCT_DEAL.PS = 'T01' AND TRD_PRODUCT_DEAL.TRADE_STATUS = '01' AND TRD_PRODUCT_DEAL.IS_CANCEL = 'N' AND L.totle_trade_id is null /*组合代码*/
and TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ and TRD_PRODUCT_DEAL.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') union all /*回购到期*/ SELECT T1.PORTFOLIO_ID, T2.PORTFOLIO_NAME, T6.FINPROD_MARKET_ID, T6.FINPROD_ABBR AS FINPROD_NAME, T6.REGIST_ORG, 0 prinAmt, /*持仓券面*/ decode(T1.FINPROD_TYPE2, 'F05', -1 *T5.PLEDGE_NUMBER * 100, 'F04', T5.PLEDGE_NUMBER * 100, 0) canpledgeAmt, /*可质押券面*/ decode(T1.FINPROD_TYPE2, 'F02', -1 *T5.PLEDGE_NUMBER * 100, 0) pledgeAmt /*已质押券面*/ FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 inner JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_DEAL_PLEDGE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN FIN_PRODUCT T6 ON T6.FINPROD_ID = T5.PLEDGE_FINPROD_ID WHERE T1.FINPROD_TYPE2 IN ('F02', 'F04', 'F05') AND t1.TRADE_STATUS = '01' AND t1.IS_CANCEL = 'N' AND t1.PS = 'T07' /*组合代码*/
and T1.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ and T1.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') union all /*债券借贷-融入 标的券*/ SELECT wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, 0 AS prinAmt ,/*持仓券面*/ SUM(NVL(wtpd.SHARE_AMT, 0)) AS canpledgeAmt,/*可质押券面*/ 0 pledgeAmt /*已质押券面*/ FROM TRD_PRODUCT_DEAL wtpd LEFT JOIN TRD_PRODUCT_DEAL_ADD wtpda ON wtpd.TRADE_ID = wtpda.TRADE_ID INNER JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join FIN_DEAL_TARGET fdt on wtpd.TRADE_ID = fdt.FINPROD_ID AND fdt.BRANCH = 0 LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = wtpd.TRADE_ID WHERE wtpd.FINPROD_TYPE2 IN ('F29') AND wtpd.PS = 'T01' AND (wtpd.IS_CANCEL IS NULL OR wtpd.IS_CANCEL = 'N') AND wtpd.TRADE_STATUS = '01' /*组合代码*/
AND wtpda.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ AND wtpd.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') GROUP BY wtpd.TRADE_ID, wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG union all /*债券借贷-融入 标的券 到期*/ SELECT wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, 0 AS prinAmt ,/*持仓券面*/ SUM(-1 * NVL(wtpd.SHARE_AMT, 0)) AS canpledgeAmt,/*可质押券面*/ 0 pledgeAmt /*已质押券面*/ FROM TRD_PRODUCT_DEAL wtpd LEFT JOIN TRD_PRODUCT_DEAL_ADD wtpda ON wtpd.TRADE_ID = wtpda.TRADE_ID INNER JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join FIN_DEAL_TARGET fdt on wtpd.FINPROD_ID = fdt.FINPROD_ID AND fdt.BRANCH = 0 LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = wtpd.TRADE_ID WHERE wtpd.FINPROD_TYPE2 IN ('F29') AND wtpd.PS = 'T07' AND (wtpd.IS_CANCEL IS NULL OR wtpd.IS_CANCEL = 'N') AND wtpd.TRADE_STATUS = '01' /*组合代码*/
AND wtpda.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ AND wtpd.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') GROUP BY wtpd.TRADE_ID, wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG union all /*债券借贷- 融入质押券*/ SELECT wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, 0 AS prinAmt,/*持仓券面*/ 0 AS canpledgeAmt,/*可质押券面*/ SUM(NVL(fdt.PLEDGE_NUMBER, 0) * 100) AS pledgeAmt /*已质押券面*/ FROM TRD_PRODUCT_DEAL wtpd LEFT JOIN TRD_PRODUCT_DEAL_ADD wtpda ON wtpd.TRADE_ID = wtpda.TRADE_ID INNER JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join FIN_DEAL_PLEDGE fdt on wtpd.TRADE_ID = fdt.FINPROD_ID AND fdt.BRANCH = 0 LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = wtpd.TRADE_ID WHERE wtpd.FINPROD_TYPE2 IN ('F29') AND wtpd.PS = 'T01' AND (wtpd.IS_CANCEL IS NULL OR wtpd.IS_CANCEL = 'N') AND wtpd.TRADE_STATUS = '01' /*组合代码*/
AND wtpda.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ AND wtpd.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') GROUP BY wtpd.TRADE_ID, wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG
union all /*债券借贷- 融入质押券*/ SELECT wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, 0 AS prinAmt,/*持仓券面*/ 0 AS canpledgeAmt,/*可质押券面*/ SUM(-1 *NVL(fdt.PLEDGE_NUMBER, 0) * 100) AS pledgeAmt /*已质押券面*/ FROM TRD_PRODUCT_DEAL wtpd LEFT JOIN TRD_PRODUCT_DEAL_ADD wtpda ON wtpd.TRADE_ID = wtpda.TRADE_ID INNER JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join FIN_DEAL_PLEDGE fdt on wtpd.FINPROD_ID = fdt.FINPROD_ID AND fdt.BRANCH = 0 LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = wtpd.TRADE_ID WHERE wtpd.FINPROD_TYPE2 IN ('F29') AND wtpd.PS = 'T07' AND (wtpd.IS_CANCEL IS NULL OR wtpd.IS_CANCEL = 'N') AND wtpd.TRADE_STATUS = '01' /*组合代码*/
AND wtpda.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ AND wtpd.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') GROUP BY wtpd.TRADE_ID, wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG union all /*债券借贷 - 融出*/ SELECT wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, 0 AS prinAmt,/*持仓券面*/ SUM(NVL(-1*wtpd.SHARE_AMT, 0)) AS canpledgeAmt,/*可质押券面*/ 0 pledgeAmt /*已质押券面*/ FROM TRD_PRODUCT_DEAL wtpd LEFT JOIN TRD_PRODUCT_DEAL_ADD wtpda ON wtpd.TRADE_ID = wtpda.TRADE_ID INNER JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join FIN_DEAL_TARGET fdt on wtpd.TRADE_ID = fdt.FINPROD_ID AND fdt.BRANCH = 0 LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = wtpd.TRADE_ID WHERE wtpd.FINPROD_TYPE2 IN ('F30') AND wtpd.PS = 'T01' AND (wtpd.IS_CANCEL IS NULL OR wtpd.IS_CANCEL = 'N') AND wtpd.TRADE_STATUS = '01' /*组合代码*/
AND wtpda.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ AND wtpd.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') GROUP BY wtpd.TRADE_ID, wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG union all
/*债券借贷 - 融出 到期*/ SELECT wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, 0 AS prinAmt,/*持仓券面*/ SUM(NVL(wtpd.SHARE_AMT, 0)) AS canpledgeAmt,/*可质押券面*/ 0 pledgeAmt /*已质押券面*/ FROM TRD_PRODUCT_DEAL wtpd LEFT JOIN TRD_PRODUCT_DEAL_ADD wtpda ON wtpd.TRADE_ID = wtpda.TRADE_ID INNER JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join FIN_DEAL_TARGET fdt on wtpd.FINPROD_ID = fdt.FINPROD_ID AND fdt.BRANCH = 0 LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fdt.PLEDGE_FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = wtpd.TRADE_ID WHERE wtpd.FINPROD_TYPE2 IN ('F30') AND wtpd.PS = 'T07' AND (wtpd.IS_CANCEL IS NULL OR wtpd.IS_CANCEL = 'N') AND wtpd.TRADE_STATUS = '01' /*组合代码*/
AND wtpda.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ AND wtpd.SETTLE_DATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') GROUP BY wtpd.TRADE_ID, wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG
union all
/*标准券入库-出库*/ SELECT TSF.PORTFOLIO_ID, PP.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR AS FINPROD_NAME, fp.REGIST_ORG, 0 AS prinAmt , 0 AS canpledgeAmt, /*持仓券面*/ sum(NVL(decode(TSF.PS, '01',TSFD.AMT,'02',-TSFD.AMT,0), 0) * 100) pledgeAmt/*已质押券面*/ FROM TRD_STASEC_FLOW TSF LEFT JOIN TRD_STASEC_FLOW_DETAIL TSFD ON TSF.SEQNO = TSFD.SEQNO inner JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = TSF.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = TSFD.FINPROD_ID
/*组合代码*/
TSF.PORTFOLIO_ID in
#{item,jdbcType=VARCHAR}
/*查询日期*/ and TSF.CDATE <= to_date(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd')
group by TSF.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.REGIST_ORG ) INFO LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_MARKET_ID=info.PORTFOLIO_ID LEFT JOIN PA_FIN_PRODUCT PFP ON PFP.FINPROD_ID=FP.FINPROD_ID where 1=1 group by INFO.PORTFOLIO_ID, INFO.PORTFOLIO_NAME, INFO.FINPROD_MARKET_ID, INFO.FINPROD_NAME, INFO.REGIST_ORG )T3 where pledgeAmt <> 0
